#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;
class Vehicle{protected:int id;string brand,model;double daily;bool available=true;public:Vehicle(int i,string b,string m,double d):id(i),brand(move(b)),model(move(m)),daily(d){}virtual~Vehicle()=default;int getId()const{return id;}bool isAvailable()const{return available;}virtual string type()const=0;virtual double rate()const{return daily;}void rent(){if(!available)throw runtime_error("vehicle unavailable");available=false;}void giveBack(){available=true;}void show()const{cout<<id<<" | "<<type()<<" | "<<brand<<' '<<model<<" | "<<rate()<<"/day | "<<(available?"Available":"Rented")<<'\n';}};class Economy:public Vehicle{public:using Vehicle::Vehicle;string type()const override{return"Economy";}double rate()const override{return daily*.9;}};class Luxury:public Vehicle{public:using Vehicle::Vehicle;string type()const override{return"Luxury";}double rate()const override{return daily*1.25;}};class SUV:public Vehicle{public:using Vehicle::Vehicle;string type()const override{return"SUV";}};
struct Rental{int id,vehicleId,days;string customer;double total;bool active=true;};class CarRental{vector<shared_ptr<Vehicle>>cars;vector<Rental>rentals;int next=1;shared_ptr<Vehicle>find(int id){for(auto&c:cars)if(c->getId()==id)return c;return{};}public:CarRental(){cars.push_back(make_shared<Economy>(1,"Toyota","Yaris",700));cars.push_back(make_shared<Luxury>(2,"BMW","520",2200));cars.push_back(make_shared<SUV>(3,"Kia","Sportage",1500));cars.push_back(make_shared<Economy>(4,"Nissan","Sunny",750));cars.push_back(make_shared<SUV>(5,"Hyundai","Tucson",1600));}void list()const{for(auto&c:cars)c->show();}void rent(){list();int id,d;string n;cout<<"Vehicle ID: ";cin>>id;auto c=find(id);if(!c||!c->isAvailable())return;cout<<"Customer: ";cin>>ws;getline(cin,n);cout<<"Days: ";cin>>d;if(d<=0)return;c->rent();double total=d*c->rate();rentals.push_back({next++,id,d,n,total,true});ofstream("rentals.txt",ios::app)<<rentals.back().id<<'|'<<id<<'|'<<n<<'|'<<d<<'|'<<total<<'\n';cout<<"Total "<<total<<'\n';}void ret(){int id;cout<<"Rental ID: ";cin>>id;for(auto&r:rentals)if(r.id==id&&r.active){r.active=false;if(auto c=find(r.vehicleId))c->giveBack();cout<<"Returned\n";return;}}void records()const{for(auto&r:rentals)cout<<r.id<<" | car "<<r.vehicleId<<" | "<<r.customer<<" | "<<r.days<<" days | "<<r.total<<" | "<<(r.active?"Active":"Returned")<<'\n';}void run(){for(;;){cout<<"\nCar Rental\n1 Cars 2 Rent 3 Return 4 Records 0 Exit\n";int c;if(!(cin>>c)||c==0)break;if(c==1)list();else if(c==2)rent();else if(c==3)ret();else if(c==4)records();}}};int main(){CarRental{}.run();}
